      "content": "// duckdb-worker.ts
import { Worker } from 'worker_threads';

export interface DuckDBWorkerMessage {
  type: 'query' | 'result' | 'error';
  data?: any;
}

export class DuckDBWorker {
  private worker: Worker;

  constructor() {
    this.worker = new Worker(new URL('./duckdb-worker.js', import.meta.url));
    this.worker.on('message', (msg: DuckDBWorkerMessage) => {
      if (msg.type === 'result') {
        console.log('Query result:', msg.data);
      } else if (msg.type === 'error') {
        console.error('Error:', msg.data);
      }
    });
  }

  public query(sql: string): void {
    this.worker.postMessage({ type: 'query', data: sql });
  }
}
